begin;
create function public.e2_validate_loan_details(input jsonb,complete boolean,price numeric) returns jsonb language plpgsql immutable set search_path='' as $fn$
declare schema constant jsonb:=$schema${"deposit":{"label":"Preferred deposit (RM)","type":"number","required":true,"max":150},"tenure":{"label":"Preferred tenure","type":["3 years","4 years","5 years","6 years","7 years","8 years","9 years"],"required":true,"max":150},"name":{"label":"Full name","type":"text","required":true,"max":150},"ic":{"label":"I/C number","type":"text","required":true,"max":150},"old_ic":{"label":"Old I/C number","type":"text","required":false,"max":150},"phone":{"label":"Mobile / WhatsApp","type":"tel","required":true,"max":150},"email":{"label":"Email","type":"email","required":true,"max":150},"marital":{"label":"Marital status","type":["Single","Married","Divorced","Widowed"],"required":true,"max":150},"phone_model":{"label":"Phone model","type":"text","required":false,"max":150},"address":{"label":"Current home address","type":"textarea","required":true,"max":300},"since":{"label":"Living here since","type":"year","required":true,"max":150},"housing":{"label":"Current residence","type":["Rented / Sewa","Parents’ home / Rumah ibu bapa","Own home / Rumah sendiri"],"required":true,"max":150},"hometown":{"label":"Hometown address","type":"textarea","required":true,"max":300},"company":{"label":"Company name","type":"text","required":true,"max":150},"position":{"label":"Position","type":"text","required":true,"max":150},"work_years":{"label":"Years employed","type":"number","required":true,"max":150},"work_months":{"label":"Additional months","type":"months","required":false,"max":150},"office_address":{"label":"Office address","type":"textarea","required":true,"max":300},"office_phone":{"label":"Office telephone","type":"tel","required":true,"max":150},"interview":{"label":"Best time for an interview call","type":["9:00 am – 12:00 pm","12:00 pm – 2:00 pm","2:00 pm – 5:00 pm","Please arrange with me"],"required":true,"max":150},"marriage_cert":{"label":"Marriage certificate available?","type":["Yes","No","Not applicable"],"required":true,"max":150},"birth_cert":{"label":"Birth certificate available?","type":["Yes","No","Not applicable"],"required":true,"max":150},"credit":{"label":"Known credit / overdue debt issues?","type":["No known issues","Yes","Not sure"],"required":true,"max":150},"debt":{"label":"Outstanding amount (RM)","type":"number","required":false,"max":150},"e1_name":{"label":"Full name","type":"text","required":true,"max":150},"e1_phone":{"label":"Phone number","type":"tel","required":true,"max":150},"e1_relation":{"label":"Relationship","type":["Spouse","Parent","Sibling","Relative","Friend","Other"],"required":true,"max":150},"e1_ic":{"label":"I/C number","type":"text","required":false,"max":150},"e1_address":{"label":"Address","type":"textarea","required":false,"max":300},"e1_position":{"label":"Occupation / position","type":"text","required":false,"max":150},"e2_name":{"label":"Full name","type":"text","required":true,"max":150},"e2_phone":{"label":"Phone number","type":"tel","required":true,"max":150},"e2_relation":{"label":"Relationship","type":["Spouse","Parent","Sibling","Relative","Friend","Other"],"required":true,"max":150},"e2_ic":{"label":"I/C number","type":"text","required":false,"max":150},"e2_address":{"label":"Address","type":"textarea","required":false,"max":300},"e2_position":{"label":"Occupation / position","type":"text","required":false,"max":150},"guarantor":{"label":"Is a guarantor needed?","type":["Not requested","Yes","Not sure"],"required":true,"max":150},"g_name":{"label":"Full name","type":"text","required":true,"max":150},"g_ic":{"label":"I/C number","type":"text","required":true,"max":150},"g_old_ic":{"label":"Old I/C number","type":"text","required":false,"max":150},"g_phone":{"label":"Mobile / WhatsApp","type":"tel","required":true,"max":150},"g_email":{"label":"Email","type":"email","required":true,"max":150},"g_marital":{"label":"Marital status","type":["Single","Married","Divorced","Widowed"],"required":true,"max":150},"g_phone_model":{"label":"Phone model","type":"text","required":false,"max":150},"g_relation":{"label":"Relationship with hirer","type":["Spouse","Parent","Sibling","Relative","Other"],"required":true,"max":150},"g_address":{"label":"Current home address","type":"textarea","required":true,"max":300},"g_since":{"label":"Living here since","type":"year","required":true,"max":150},"g_housing":{"label":"Current residence","type":["Rented / Sewa","Parents’ home / Rumah ibu bapa","Own home / Rumah sendiri"],"required":true,"max":150},"g_hometown":{"label":"Hometown address","type":"textarea","required":true,"max":300},"g_company":{"label":"Company name","type":"text","required":true,"max":150},"g_position":{"label":"Position","type":"text","required":true,"max":150},"g_work_years":{"label":"Years employed","type":"number","required":true,"max":150},"g_work_months":{"label":"Additional months","type":"months","required":false,"max":150},"g_office_address":{"label":"Office address","type":"textarea","required":true,"max":300},"g_office_phone":{"label":"Office telephone","type":"tel","required":true,"max":150},"g_interview":{"label":"Best time for an interview call","type":["9:00 am – 12:00 pm","12:00 pm – 2:00 pm","2:00 pm – 5:00 pm","Please arrange with me"],"required":true,"max":150},"g_marriage_cert":{"label":"Marriage certificate available?","type":["Yes","No","Not applicable"],"required":true,"max":150},"g_birth_cert":{"label":"Birth certificate available?","type":["Yes","No","Not applicable"],"required":true,"max":150},"g_credit":{"label":"Known credit / overdue debt issues?","type":["No known issues","Yes","Not sure"],"required":true,"max":150},"g_debt":{"label":"Outstanding amount (RM)","type":"number","required":false,"max":150}}$schema$::jsonb; clean jsonb:='{}'; k text; value text; spec jsonb; enabled boolean;
begin
 if jsonb_typeof(input) is distinct from 'object' or octet_length(input::text)>30000 then raise exception 'Enter valid application details.';end if;
 for k in select jsonb_object_keys(input) loop
  if not schema ? k then raise exception 'Unknown application field: %',k;end if;
  if jsonb_typeof(input->k) is distinct from 'string' then raise exception 'Invalid field format: %',k;end if;
 end loop;
 for k,spec in select * from jsonb_each(schema) loop
  enabled:=(left(k,2)<>'g_' or input->>'guarantor'='Yes') and (k<>'debt' or input->>'credit'='Yes') and (k<>'g_debt' or input->>'g_credit'='Yes');
  if enabled is not true then continue;end if;
  value:=trim(coalesce(input->>k,''));
  if complete and (spec->>'required')::boolean and value='' then raise exception 'Complete: %',spec->>'label';end if;
  if length(value)>(spec->>'max')::int then raise exception 'Field is too long: %',spec->>'label';end if;
  if value<>'' then
   if jsonb_typeof(spec->'type')='array' and not (spec->'type') ? value then raise exception 'Choose a valid option: %',spec->>'label';end if;
   if spec->>'type' in ('number','months','year') then
    if value !~ '^[0-9]{1,9}$' then raise exception 'Enter a whole positive number: %',spec->>'label';end if;
    if (k='deposit' and value::numeric>price) or (spec->>'type'='months' and value::int>11) or (spec->>'type'='year' and value::int not between 1940 and 2100) or (k like '%work_years' and value::int>80) then raise exception 'Number outside range: %',spec->>'label';end if;
   end if;
   if complete and spec->>'type'='email' and value !~ '^[^ @]+@[^ @]+[.][^ @]+$' then raise exception 'Enter a valid email.';end if;
   if complete and spec->>'type'='tel' and regexp_replace(value,'[^0-9]','','g') !~ '^[0-9]{8,15}$' then raise exception 'Enter a valid telephone number.';end if;
  end if;
  clean:=clean||jsonb_build_object(k,value);
 end loop;
 return clean;
end;$fn$;
revoke all on function public.e2_validate_loan_details(jsonb,boolean,numeric) from public,anon,authenticated;
commit;
